head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jlddst50200";

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jlddst50200.onpageload' });
    }
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_pageBody = async function () {
    try {
        await scwin.fnInit();

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jlddst50200.onpageload' }); }
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { /* TODO Stage2: [sdd] 전환 파라미터 수신 대상 없음: dma_pageContext — 읽는 자리 0 */ };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_fnTabClick_onclick
 * @description btn_fnTabClick 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_fnTabClick_onclick = async function(e){
    try {
        await scwin.fnTabClick(0)

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jlddst50200.btn_fnTabClick_onclick' }); }
};

/**
 * @method
 * @name btn_fnTabClick_2_onclick
