/**
 * @method
 * @name btn_fnPopClose_onclick
 * @description btn_fnPopClose 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_fnPopClose_onclick = function(e){
    try {
        fnPopClose(); return false;

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jlddst50200.btn_fnPopClose_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fnSearch_ajaxsubmit
 * @description fn Search ajaxsubmit 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fnSearch_ajaxsubmit = async function () {
    const sbmOptions = {
        id: "tx_fnSearch_ajaxsubmit",
        method: "post",
        action: "/owlDisclsList.do",
        ref: "dma_fnSearchAjaxsubmitReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name fnInit
 * @description fn Init 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnInit = async function () {
    $c.util.getComponent("dma_fnSearchAjaxsubmitReq").set("orderMode", "0");
    $c.util.getComponent("dma_fnSearchAjaxsubmitReq").set("orderStat", "D");
    $c.util.getComponent("dma_fnSearchAjaxsubmitReq").set("pageIndex", "1");
    await scwin.fnSearch();
};

/**
 * @method
 * @name fnOrder
 * @description fn Order 처리
 * @param {*} mode mode
 * @param {*} stat stat
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnOrder = async function (mode, stat) {
    $c.util.getComponent("dma_fnSearchAjaxsubmitReq").set("orderMode", mode);
    $c.util.getComponent("dma_fnSearchAjaxsubmitReq").set("orderStat", stat);
    $c.util.getComponent("dma_fnSearchAjaxsubmitReq").set("pageIndex", "1");
    await scwin.fnSearch();
};

/**
 * @method
 * @name fnSearch
 * @description fn Search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnSearch = async function () {
    $c.util.getComponent("dma_fnSearchAjaxsubmitReq").set("method", "searchOwlDisclsList");
    $c.util.getComponent("dma_fnSearchAjaxsubmitReq").set("forward", "searchOwlDisclsListSub");
    await scwin.tx_fnSearch_ajaxsubmit();
};

/**
 * @method
 * @name fnSearchCallBack
 * @description fn Search Call Back 처리
 * @param {*} data 데이터
 * @returns {void}
 * @hidden N
 */
scwin.fnSearchCallBack = function (data) {
    $("#mainContents").empty().append(data);
    $("tr:even").addClass("active");
    /* TODO Stage2: [sdd] 미실현(재설계 분류 #128): fnLegendTooltip( " ') */
};

/**
 * @method
 * @name fnSearch1
 * @description fn Search1 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnSearch1 = async function () {
    $c.util.getComponent("dma_fnSearchAjaxsubmitReq").set("pageIndex", "1");
    $c.util.getComponent("dma_fnSearchAjaxsubmitReq").set("currentPageSize", $(document).find("select[id=ipt_currentPageSize]").val());
    await scwin.fnSearch();
};

/**
 * @method
 * @name fnTabClick
 * @description fn Tab Click 처리
 * @param {Number} idx idx
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnTabClick = async function (idx) {
    $(document).find("li[id=marketType]").each(function(i) {
            if ($(this).hasClass("active")) {
                $(this).removeClass("active");
            }
            if (i === idx) {
                $(this).addClass("active");
            }
    });
    let marketType = idx;
    if (idx === "3") {
        marketType = "6";
    } else {
        if (idx === "0") {
            marketType = "";
        }
    }
    $c.util.getComponent("dma_fnSearchAjaxsubmitReq").set("marketType", marketType);
    await scwin.fnInit();
};
